class Solution {
    public int[] circularGameLosers(int n,int k){
        boolean[] visited=new boolean[n];
        int current=0,round=1;
        while(!visited[current]){
            visited[current]=true;
            current=(current+round*k)%n;
            round++;
        }
        int count=0;
        for(boolean value:visited)if(!value)count++;
        int[] answer=new int[count];
        for(int i=0,index=0;i<n;i++)if(!visited[i])answer[index++]=i+1;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun circularGameLosers(n:Int,k:Int):IntArray{
        val visited=BooleanArray(n);
        var current=0;
        var round=1;
        while(!visited[current]){
            visited[current]=true;
            current=(current+round*k)%n;
            round++
        };
        return (0 until n).filter{
            !visited[it]
        }.map{
            it+1
        }.toIntArray()
    }
}

